<?php $ph=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8'); ?>
<?php if($employee): ?><section class="payroll-tools"><h2>Allowance settings · <?= $ph($employee['full_name']) ?></h2><p>HR controls eligibility and the allowance for each 15-day cutoff. Saved payslips retain their original amount until regenerated.</p><form method="post" class="payroll-profile-form"><input type="hidden" name="csrf_token" value="<?= $ph($_SESSION['payroll_csrf']) ?>"><input type="hidden" name="action" value="save_allowance"><input type="hidden" name="employee_id" value="<?= $employeeId ?>"><input type="hidden" name="cutoff_start" value="<?= $ph($cutoffStart) ?>"><label class="payroll-checkbox"><input type="checkbox" name="is_tenured" value="1" <?= $profile['is_tenured']?'checked':'' ?>> Existing staff eligible for automatic allowance</label><label>Amount per 15-day cutoff (PHP)<input name="allowance_amount" type="number" min="0" max="99999999.99" step="0.01" required value="<?= $ph(number_format((float)$profile['allowance'],2,'.','')) ?>"></label><label>Effective from (optional)<input type="date" name="effective_from" value="<?= $ph($profile['effective_from']??'') ?>"></label><label>HR notes<textarea name="allowance_notes" rows="2" maxlength="1000"><?= $ph($profile['notes']) ?></textarea></label><button type="submit">Save allowance settings</button></form></section><?php endif ?>
